function validate(input) {
  const [{ Subscriptions = [], Streams = [] }] = input;
  const isDate = value => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value);
  const accounts = new Set(), sessions = new Set();
  for (const [account, start, end] of Subscriptions) {
    if (account === null) return 'Every subscription needs an account_id.';
    if (accounts.has(account)) return `account_id ${account} appears twice in Subscriptions.`;
    accounts.add(account);
    if (!isDate(start) || !isDate(end)) return `Account ${account} needs YYYY-MM-DD start and end dates.`;
    if (start > end) return `Account ${account} ends before it starts.`;
  }
  for (const [session, account, date] of Streams) {
    if (session === null) return 'Every stream needs a session_id.';
    if (sessions.has(session)) return `session_id ${session} appears twice in Streams.`;
    sessions.add(session);
    if (!accounts.has(account)) return `Session ${session} names unknown account ${account}.`;
    if (!isDate(date)) return `Session ${session} needs a YYYY-MM-DD stream_date.`;
  }
  return null;
}

