function generate(rand, size) {
  const day = offset => new Date(Date.UTC(2019, 0, 1) + offset * 86400000).toISOString().slice(0, 10);
  const Subscriptions = [], Streams = [];
  if (size === 'small') {
    // Dates cluster on the year boundaries so that "active in 2021" and "streamed in 2021" are tested at their edges.
    const dates = ['2019-11-30', '2020-05-16', '2020-12-31', '2021-01-01', '2021-03-15', '2021-08-08', '2021-12-31', '2022-01-01', '2022-04-10'];
    const pick = () => dates[Math.floor(rand() * dates.length)];
    const accounts = Math.floor(rand() * 7);
    for (let id = 1; id <= accounts; id++) {
      const [a, b] = [pick(), pick()].sort();
      Subscriptions.push([id + 2, a, b]);
    }
    const sessions = accounts ? Math.floor(rand() * 9) : 0;
    for (let s = 1; s <= sessions; s++) Streams.push([s + 10, Subscriptions[Math.floor(rand() * accounts)][0], pick()]);
    return [{ Subscriptions, Streams }];
  }
  // Large: four years of dates, 2,000 accounts and 2,000 sessions.
  for (let id = 1; id <= 2000; id++) {
    const start = Math.floor(rand() * 1300);
    Subscriptions.push([id, day(start), day(start + Math.floor(rand() * 500))]);
  }
  for (let s = 1; s <= 2000; s++) Streams.push([s, 1 + Math.floor(rand() * 2000), day(Math.floor(rand() * 1460))]);
  return [{ Subscriptions, Streams }];
}
